from fclib import *
b = Board('Flowchart_Rules', 'Rules', 1280, 2060, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}.tbl{display:grid;gap:8px 12px;font-size:13px;line-height:20px;color:#334155;align-items:center}</style>'''
def mini(kind, w=64, h=34):
    return f'<div style="position:relative;width:{w}px;height:{h}px">{shape_svg(kind, w, h)}</div>'
shapes = [('terminator', 'Terminator', 'Start and end of a flow. Green. A failed end is rose.'),
          ('process', 'Process', 'One action. Blue.'),
          ('decision', 'Decision', 'A question with two or more exits. Amber.'),
          ('io', 'Input / output', 'Data entering or leaving. Violet.'),
          ('document', 'Document', 'A readable output. White.'),
          ('subprocess', 'Subprocess', 'A step defined as its own chart. Blue with side bars.'),
          ('preparation', 'Preparation', 'Setup or initialisation. Teal.'),
          ('connector', 'Connector', 'Off-page link, one letter. Rose.')]
rows = ''.join(f'{mini(k, 64 if k!="connector" else 34, 34)}<b>{n}</b><span>{t}</span>' for k, n, t in shapes)
lines = [('border-top:2px solid #0F172A', 'Next step: ink, solid'), ('border-top:2px solid #15803D', 'Yes or success: green'), ('border-top:2px solid #B42318', 'No or failure: rose'), ('border-top:2px dashed #475569', 'Return, retry or loop: slate, dashed')]
lrows = ''.join(f'<span style="width:34px;{s}"></span><span>{t}</span>' for s, t in lines)
lrows += '<svg width="34" height="8" viewBox="0 0 34 8" style="fill:none;stroke:#1D4ED8;stroke-width:4;stroke-dasharray:8 5"><path d="M0 4L34 4"/></svg><span>Main path: blue, thick, animated fast. One per chart; it may split at a fork.</span>'
lrows += '<svg width="34" height="8" viewBox="0 0 34 8" style="fill:none;stroke:#7C3AED;stroke-width:2;stroke-dasharray:6 6"><path d="M0 4L34 4"/></svg><span>Data stream: violet, thin, animated slowly. Messages and live data, not steps.</span>'
sizes = [('Terminator', '150 × 48'), ('Process', '160 × 56'), ('Decision', '170 × 100'), ('Input / output', '190 × 56'), ('Document', '130 × 60'), ('Subprocess', '160 × 56'), ('Preparation', '140 × 56'), ('Connector', '38 × 38')]
srows = ''.join(f'<span>{n}</span><span class="mono">{s}</span>' for n, s in sizes)
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('Shapes and colours', f'<div class="tbl" style="grid-template-columns:70px 120px 1fr">{rows}</div>'),
 card('Line roles', f'<div style="display:grid;grid-template-columns:auto 1fr;gap:12px 14px;align-items:center;font-size:13px;color:#334155">{lrows}</div>' + ul('Arrowheads are always filled. An arrow leaves the middle of an edge and enters the middle of the next.', 'Labels sit on a pill beside the line, never across a shape.')),
 card('Text in nodes', ul('A process starts with a verb: <i>Check stock</i>, <i>Send email</i>. A terminator names the state: <i>Order placed</i>.', 'Four words or fewer, sentence case, two lines at most.', 'Never wrap a label by hand. Widen the node instead.', 'Input / output names the data: <i>Read file</i>. A document is a noun: <i>Report</i>.')),
 card('Decisions', ul('The text is a question that ends with a question mark and has a clear answer.', 'Two exits are labelled <b>Yes</b> and <b>No</b>. More exits are labelled with their value and the last is <i>else</i>.', 'Yes continues straight along the flow. No leaves sideways or downward, so the happy path stays on one line.', 'Every exit leads somewhere. A decision with one exit is a process.')),
 card('Direction and layout', ul('Top to bottom for up to about ten steps, left to right for pipelines and timelines. Do not mix both in one chart.', 'Steps in a row share a centre line. Gap between steps: 56 px or more vertical, 70 px or more horizontal.', 'Return arrows run outside the flow, around the steps and never through one.', 'Start in the top left. End in the bottom or the right.', 'When a chart outgrows one page, cut it with an off-page connector or move a block into a subprocess.')),
 card('Sizes', f'<div class="tbl" style="grid-template-columns:1fr 1fr">{srows}</div><div style="font-size:12px;line-height:18px;color:#475569">Sizes are minimums. Widen a shape to fit its text, keep its height, and keep widths equal within a column.</div>'),
 card('Swimlanes', ul('One lane per actor: person, team or system. A step sits in exactly one lane.', 'The actor who starts the process goes in the top lane.', 'A line that changes lane runs straight across it, at a right angle, and never through a card.', 'Steps that follow each other may stack in one column across lanes. Lane height: 210 px with plain nodes, 240 px with cards.', 'Lane colours reuse the zone tints (blue, violet, green). Lane label on the left, white on a solid band.')),
 card('Numbers, connectors and subprocess', ul('Number chips are optional. Use them when other text refers to steps. Branches add a letter: 3a.', 'A connector circle holds one letter. The same letter starts the next chart, and a note says where it continues.', 'A subprocess keeps the name of its own chart exactly.')),
 card('Animation', ul('Two tiers, no more. The main path is blue, thick and fast: the one route that matters. A second animated line of the same kind cancels the effect.', 'A data stream is violet, thin and slow. It carries messages or live data between lanes and never counts as the main path.', 'Yes, No and return lines stay static.', 'Animation is off when the viewer prefers reduced motion.', 'In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('Two styles', ul('<b>Plain</b> is the default: shapes with text, an optional small icon. Use it for drafts, technical charts and anything that will change often.', '<b>Illustrated</b> turns work steps into cards with a name pill, one line of explanation and a large icon, tinted by lane. Use it for steps people must notice, or for readers outside the team.', 'The two share every rule on this page. Only node shape and spacing differ (see Illustrated nodes).', 'Styles mix in one chart. A chart uses one style unless the author says otherwise.')),
 card('Icons', ul('Small icon on a plain node: 18 px, from the flat set, in the stroke colour of the shape.', 'Large icon on a card: 64 px, from the detailed set. Every flat icon has a detailed twin with the same name.', 'Choose by the noun (Card for payment, Cart for order). One icon per node, the same icon for the same thing.', 'An icon never replaces the text.')),
 card('What a plugin can rely on', ul('A node is: ID, kind, text, optional lane, number, icon and (illustrated only) a one-line description.', 'An edge is: from, to, role (next, yes, no, back, main, data) and optional label.', 'A chart has a style, plain or illustrated, and an optional list of lanes.', 'Layout comes from ranks: the longest path is placed on a straight line first, then branches are added to the side.', 'Sizes, gaps and colours come from this page, so two charts of the same content look the same.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">Flowchart · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">The conventions every flowchart follows, and that a plugin can rely on. Patterns shows the common structures, Illustrated nodes the richer style, and the examples show both in use.</div></div>{grid}</div>')
print(b.save())
